export function normalizeRegistryKey(s: string): string {
  return String(s || "")
    .normalize("NFD")
    .replace(/[\u0300-\u036f]/g, "")
    .toLowerCase()
    .replace(/\$/g, "s")
    .replace(/&/g, "and")
    .replace(/[\x27\u2018\u2019`".]/g, "")
    .replace(/[^a-z0-9]+/g, " ")
    .trim();
}

export function cleanRegistryTitleKey(s: string): string {
  return normalizeRegistryKey(
    String(s || "")
      .replace(/\s*\((feat|ft|with|from|deluxe|bonus|explicit|clean|remaster|taylor|s version|edition|version|single|official|music video|audio|live)[^)]*\)/gi, "")
      .replace(/\s*\[[^\]]*\]/g, "")
      .replace(/\s*-\s*(single|ep|deluxe.*|remaster.*|from .*|taylor.*)/gi, "")
  );
}

export function sanitizeArtworkCdnUrl(url: string | null | undefined): string | null {
  if (!url || typeof url !== "string") return null;
  if (!url.startsWith("http")) return url;
  return url
    .replace(/\{w\}x\{h\}/g, "600x600")
    .replace(/\{c\}/g, "bb")
    .replace(/\{f\}/g, "jpg")
    .replace(/100x100bb/g, "600x600bb");
}

export function getVerifiedSpotifyNpcPortrait(artistName: string): string | null {
  if (!artistName) return null;
  const raw = String(artistName).trim();
  const primary = raw.split(/\s+(?:&|feat\.|ft\.|with|,)\s+/i)[0].trim();
  const hit =
    VERIFIED_SPOTIFY_NPC_PORTRAITS[normalizeRegistryKey(raw)] ||
    VERIFIED_SPOTIFY_NPC_PORTRAITS[normalizeRegistryKey(primary)] ||
    VERIFIED_SPOTIFY_NPC_PORTRAITS[raw.toLowerCase()] ||
    VERIFIED_SPOTIFY_NPC_PORTRAITS[primary.toLowerCase()] ||
    null;
  return sanitizeArtworkCdnUrl(hit);
}

export function getVerifiedOfficialReleaseCover(
  artistName: string,
  title?: string,
  isAlbum = false,
  parentAlbumHint?: string
): string | null {
  if (!artistName || !title) return null;
  const rawArtist = String(artistName).trim();
  const primaryArtist = rawArtist.split(/\s+(?:&|feat\.|ft\.|with|,)\s+/i)[0].trim();
  const rawTitle = String(title)
    .replace(/\s*\((Official Music Video|Official Video|Music Video|Video Oficial|Vídeo Oficial|Lyric Video|Visualizer|Live|Performance Video)\)/gi, "")
    .trim();

  const candidateArtistKeys = Array.from(
    new Set([
      normalizeRegistryKey(rawArtist),
      normalizeRegistryKey(primaryArtist),
      rawArtist.toLowerCase(),
      primaryArtist.toLowerCase()
    ])
  ).filter(Boolean);

  const candidateTitleKeys = Array.from(
    new Set([
      normalizeRegistryKey(rawTitle),
      cleanRegistryTitleKey(rawTitle),
      rawTitle.toLowerCase()
    ])
  ).filter(Boolean);

  const primaryDict = isAlbum ? VERIFIED_OFFICIAL_ALBUM_COVERS : VERIFIED_OFFICIAL_SONG_COVERS;
  const secondaryDict = isAlbum ? VERIFIED_OFFICIAL_SONG_COVERS : VERIFIED_OFFICIAL_ALBUM_COVERS;

  for (const aKey of candidateArtistKeys) {
    for (const tKey of candidateTitleKeys) {
      const composite = `${aKey}::${tKey}`;
      if (primaryDict[composite]) {
        return sanitizeArtworkCdnUrl(primaryDict[composite]);
      }
    }
  }

  for (const aKey of candidateArtistKeys) {
    for (const tKey of candidateTitleKeys) {
      const composite = `${aKey}::${tKey}`;
      if (secondaryDict[composite]) {
        return sanitizeArtworkCdnUrl(secondaryDict[composite]);
      }
    }
  }

  if (parentAlbumHint) {
    const parentTitleKeys = [
      normalizeRegistryKey(parentAlbumHint),
      cleanRegistryTitleKey(parentAlbumHint),
      parentAlbumHint.toLowerCase().trim()
    ].filter(Boolean);
    for (const aKey of candidateArtistKeys) {
      for (const pKey of parentTitleKeys) {
        const composite = `${aKey}::${pKey}`;
        if (VERIFIED_OFFICIAL_ALBUM_COVERS[composite]) {
          return sanitizeArtworkCdnUrl(VERIFIED_OFFICIAL_ALBUM_COVERS[composite]);
        }
      }
    }
  }

  return null;
}
